// M5 prediction: "at your pace you'll know X words by <date>" — pure
// interpolation over an offline-simulated table (assets/prediction_table.json,
// generated by scripts/app_pipeline/gen_prediction_table.mjs).
//
// The table is produced by forward-simulating a FRESH learner through the
// REAL engine (scheduler + picker + graduation, real corpus) for several
// minutes-per-day tracks. On device we only interpolate — no simulation, no
// growth formula (locked: curve shape comes from the real engine).
//
// Approximations (documented, deliberate):
// - Between two minutes tracks: linear interpolation in minutes at each
//   shared checkpoint day (the generator emits every track on one day grid).
// - Anchoring: the table starts from zero, a real user is already somewhere
//   along the curve. We find the day-offset t0 where the interpolated track's
//   heard-count equals the user's currentHeard and continue from t0. This
//   assumes past pace roughly matched present pace; it guarantees the
//   forecast is continuous with the observed curve (day 0 = currentHeard).
// - graduated is shifted additively so day 0 matches the user's actual
//   graduated count, then clamped into [0, heard].
// - No extrapolation: beyond the simulated horizon, or when currentHeard
//   exceeds the track's ceiling, the curve goes flat. minutes below the
//   lowest track clamp up to it (floor 10); above the highest clamp down.
// - medianMinutes <= 0 (no listening history) → flat line at current counts.

export interface PredictionTable {
  horizonDays: number
  /** ascending minutes-per-day tracks; each point is [day, heard, graduated] */
  tracks: { minutes: number, points: number[][] }[]
}

export interface PredictedPoint {
  /** days from today (0 = today) */
  day: number
  heard: number
  graduated: number
}

export interface PredictionMilestone {
  months: number
  /** day-offset used for this milestone */
  day: number
  heard: number
  graduated: number
}

export const MILESTONE_MONTHS: readonly { months: number, days: number }[] = [
  { months: 3, days: 91 },
  { months: 6, days: 182 },
  { months: 12, days: 365 },
  { months: 24, days: 730 },
]

function clamp(v: number, lo: number, hi: number): number {
  return Math.min(hi, Math.max(lo, v))
}

/** piecewise-linear read of a track at (possibly fractional) day t, clamped at both ends */
function valueAt(points: number[][], t: number): { heard: number, graduated: number } {
  const first = points[0]
  const last = points[points.length - 1]
  if (t <= first[0]) return { heard: first[1], graduated: first[2] }
  if (t >= last[0]) return { heard: last[1], graduated: last[2] }
  for (let i = 1; i < points.length; i++) {
    if (t <= points[i][0]) {
      const [d0, h0, g0] = points[i - 1]
      const [d1, h1, g1] = points[i]
      const f = (t - d0) / (d1 - d0)
      return { heard: h0 + f * (h1 - h0), graduated: g0 + f * (g1 - g0) }
    }
  }
  return { heard: last[1], graduated: last[2] }
}

/**
 * Blend the two tracks bracketing `minutes` (linear in minutes per checkpoint).
 * Minutes outside the swept range clamp to the nearest track.
 */
export function interpolateTrack(table: PredictionTable, minutes: number): number[][] {
  const tracks = [...table.tracks].sort((a, b) => a.minutes - b.minutes)
  if (tracks.length === 0) return [[0, 0, 0]]
  const m = clamp(minutes, tracks[0].minutes, tracks[tracks.length - 1].minutes)
  let lo = tracks[0]
  let hi = tracks[tracks.length - 1]
  for (let i = 1; i < tracks.length; i++) {
    if (m <= tracks[i].minutes) { lo = tracks[i - 1]; hi = tracks[i]; break }
  }
  const f = hi.minutes === lo.minutes ? 0 : (m - lo.minutes) / (hi.minutes - lo.minutes)
  return lo.points.map((p, i) => {
    const q = hi.points[i] ?? p // grids match by construction; degrade gracefully
    return [p[0], p[1] + f * (q[1] - p[1]), p[2] + f * (q[2] - p[2])]
  })
}

/**
 * Day-offset on the track where cumulative heard equals `currentHeard`
 * (inverse piecewise-linear). null = beyond the track's ceiling (no forecast).
 */
function anchorDay(points: number[][], currentHeard: number): number | null {
  if (currentHeard <= points[0][1]) return points[0][0]
  const last = points[points.length - 1]
  if (currentHeard > last[1]) return null
  for (let i = 1; i < points.length; i++) {
    if (currentHeard <= points[i][1]) {
      const [d0, h0] = points[i - 1]
      const [d1, h1] = points[i]
      if (h1 === h0) return d0
      return d0 + ((currentHeard - h0) / (h1 - h0)) * (d1 - d0)
    }
  }
  return last[0]
}

/**
 * Forecast the words curve from today out to `horizonDays`, sampled every
 * `stepDays` (last point always exactly at horizonDays). Day 0 is anchored
 * to `currentHeard` (and `currentGraduated` when given).
 */
export function predictCurve(
  table: PredictionTable,
  medianMinutes: number,
  currentHeard: number,
  horizonDays: number,
  opts: { stepDays?: number, currentGraduated?: number } = {},
): PredictedPoint[] {
  if (horizonDays <= 0) return []
  const stepDays = Math.max(1, Math.round(opts.stepDays ?? 30))
  const days: number[] = []
  for (let d = 0; d < horizonDays; d += stepDays) days.push(d)
  days.push(horizonDays)

  const flat = (): PredictedPoint[] => {
    const g = Math.round(clamp(opts.currentGraduated ?? 0, 0, currentHeard))
    return days.map(day => ({ day, heard: currentHeard, graduated: g }))
  }

  if (medianMinutes <= 0) return flat()
  const points = interpolateTrack(table, medianMinutes)
  const t0 = anchorDay(points, currentHeard)
  if (t0 === null) return flat()

  const gradShift = opts.currentGraduated !== undefined
    ? opts.currentGraduated - valueAt(points, t0).graduated
    : 0

  return days.map(day => {
    const v = valueAt(points, t0 + day)
    const heard = Math.round(Math.max(currentHeard, v.heard))
    const graduated = Math.round(clamp(v.graduated + gradShift, 0, heard))
    return { day, heard, graduated }
  })
}

/** Words known at +3 / +6 / +12 / +24 months, same anchoring as predictCurve. */
export function predictionMilestones(
  table: PredictionTable,
  medianMinutes: number,
  currentHeard: number,
  currentGraduated?: number,
): PredictionMilestone[] {
  return MILESTONE_MONTHS.map(({ months, days }) => {
    const curve = predictCurve(table, medianMinutes, currentHeard, days,
      { stepDays: days, currentGraduated })
    const last = curve[curve.length - 1]
    return { months, day: days, heard: last.heard, graduated: last.graduated }
  })
}
